public static void main( String[] args ){
  Scanner scan = new Scanner(System.in);

  int n = scan.nextInt();
  int x = scan.nextInt();
  int y = scan.nextInt();
  int z = scan.nextInt();

  // Determine if the travel is inbound or outbound
  if (x < y) { // Inbound travel
    if (x < z && z < y) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  } else { // Outbound travel
    if (y < z && z < x) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  }
}

